<?php

declare(strict_types=1);

namespace Database\Seeders;

use Illuminate\Database\Seeder;
use Onhost\Domain\Notifications\Models\NotificationTemplate;

/**
 * Versioned, localized transactional templates (blueprint §72). Re-running keeps the
 * version when the body is unchanged and bumps it when the text changed, so old mails
 * remain reproducible. Placeholders: {{name}}.
 */
final class NotificationTemplateSeeder extends Seeder
{
    public function run(): void
    {
        foreach ($this->templates() as $key => $t) {
            foreach (['cs', 'en'] as $locale) {
                $this->upsert($key, $locale, $t[$locale]['subject'], $t[$locale]['body'], $t['vars'], (bool) ($t['mandatory'] ?? false));
            }
        }
    }

    private function upsert(string $key, string $locale, string $subject, string $body, array $vars, bool $mandatory): void
    {
        $current = NotificationTemplate::query()->where('key', $key)->where('channel', 'mail')->where('locale', $locale)->orderByDesc('version')->first();
        if ($current !== null && $current->subject === $subject && $current->body === $body) {
            $current->forceFill(['variables' => $vars, 'mandatory' => $mandatory, 'state' => 'active'])->save();

            return;
        }
        NotificationTemplate::query()->create(['key' => $key, 'channel' => 'mail', 'locale' => $locale, 'version' => ($current?->version ?? 0) + 1, 'subject' => $subject, 'body' => $body, 'variables' => $vars, 'mandatory' => $mandatory, 'state' => 'active']);
        if ($current !== null) {
            $current->forceFill(['state' => 'superseded'])->save();
        }
    }

