            'domain-renewal-failed' => ['mandatory' => true, 'vars' => ['domena', 'duvod', 'url'], 'cs' => ['subject' => 'Prodloužení domény {{domena}} se nezdařilo', 'body' => "Doménu {{domena}} se nepodařilo prodloužit: {{duvod}}.\n\nDobijte kredit nebo prodlužte ručně, jinak doména expiruje: {{url}}".$sig['cs']], 'en' => ['subject' => 'Renewing domain {{domena}} failed', 'body' => "Domain {{domena}} could not be renewed: {{duvod}}.\n\nTop up or renew manually, otherwise the domain expires: {{url}}".$sig['en']]],
